class LmdbLearningKeyabilityTest {

	@Test
	void learnedFilterSurfacesLeaveUnauditedRowsForExecution() {
		AtomicInteger opens = new AtomicInteger();
		Filter filter = new Filter(unauditedRows(opens), new Bound(new Var("x")));
		assertNull(FilterSurfaceKey.exact(filter));
		assertNull(FilterSurfaceKey.generalized(filter));
		assertEquals(0, opens.get(), "learning must decline before opening a single-use input");
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void semiAntiSurfaceDeclinesUnauditedOuterAndInnerRows(boolean negated) {
		AtomicInteger outerOpens = new AtomicInteger();
		AtomicInteger innerOpens = new AtomicInteger();
		Filter outer = exists(unauditedRows(outerOpens), new SingletonSet(), negated);
		Filter inner = exists(new SingletonSet(), unauditedRows(innerOpens), negated);
		String kind = negated ? "not-exists" : "exists";
		assertNull(SemiAntiSurfaceKey.from(outer, kind, "streaming"));
		assertNull(SemiAntiSurfaceKey.from(inner, kind, "streaming"));
		assertEquals(0, outerOpens.get());
		assertEquals(0, innerOpens.get());
	}

	@Test
	void auditedImmutableRowsKeepFilterAndSemiAntiLearningAvailable() {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of("x"));
		assignment.setBindingSets(List.of(new ListBindingSet(List.of("x"),
				SimpleValueFactory.getInstance().createIRI("urn:keyability:value"))));
		Filter filter = new Filter(assignment, new Bound(new Var("x")));
		assertNotNull(FilterSurfaceKey.exact(filter));
		assertNotNull(FilterSurfaceKey.generalized(filter));
		assertNotNull(SemiAntiSurfaceKey.from(exists(new SingletonSet(), assignment, false), "exists", "streaming"));
	}

	private static Filter exists(TupleExpr outer, TupleExpr inner, boolean negated) {
		Exists exists = new Exists(inner);
		return new Filter(outer, negated ? new Not(exists) : exists);
	}

	private static BindingSetAssignment unauditedRows(AtomicInteger opens) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of("x"));
		assignment.setBindingSets(new Iterable<BindingSet>() {
			@Override
			public Iterator<BindingSet> iterator() {
				opens.incrementAndGet();
				throw new AssertionError("learning must not open unaudited rows");
			}
		});
		return assignment;
	}
}
